BEGIN;
CREATE TABLE IF NOT EXISTS public.iara_forecasts(forecast_id UUID PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,execution_id UUID,metric TEXT NOT NULL,horizon INTEGER NOT NULL CHECK(horizon BETWEEN 1 AND 168),model_version TEXT NOT NULL,confidence NUMERIC NOT NULL CHECK(confidence BETWEEN 0 AND 1),data_quality NUMERIC NOT NULL CHECK(data_quality BETWEEN 0 AND 1),evidence_count INTEGER NOT NULL CHECK(evidence_count>=0),points JSONB NOT NULL DEFAULT '[]'::jsonb,drivers JSONB NOT NULL DEFAULT '[]'::jsonb,limitations JSONB NOT NULL DEFAULT '[]'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_iara_forecasts_tenant_metric_created ON public.iara_forecasts(tenant_id,metric,created_at DESC);
CREATE TABLE IF NOT EXISTS public.iara_causal_diagnoses(diagnosis_id UUID PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,execution_id UUID,metric TEXT NOT NULL,observed_effect NUMERIC NOT NULL,candidate_causes JSONB NOT NULL DEFAULT '[]'::jsonb,confounders JSONB NOT NULL DEFAULT '[]'::jsonb,counterfactual TEXT NOT NULL,causal_conclusion TEXT NOT NULL CHECK(causal_conclusion IN('SUPPORTED','INSUFFICIENT_EVIDENCE','CONTRADICTED')),confidence NUMERIC NOT NULL CHECK(confidence BETWEEN 0 AND 1),evidence_coverage NUMERIC NOT NULL CHECK(evidence_coverage BETWEEN 0 AND 1),recommended_actions JSONB NOT NULL DEFAULT '[]'::jsonb,limitations JSONB NOT NULL DEFAULT '[]'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_iara_causal_tenant_metric_created ON public.iara_causal_diagnoses(tenant_id,metric,created_at DESC);
ALTER TABLE public.iara_forecasts ENABLE ROW LEVEL SECURITY; ALTER TABLE public.iara_causal_diagnoses ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS iara_forecasts_select_own ON public.iara_forecasts; CREATE POLICY iara_forecasts_select_own ON public.iara_forecasts FOR SELECT TO authenticated USING(tenant_id=auth.uid());
DROP POLICY IF EXISTS iara_causal_diagnoses_select_own ON public.iara_causal_diagnoses; CREATE POLICY iara_causal_diagnoses_select_own ON public.iara_causal_diagnoses FOR SELECT TO authenticated USING(tenant_id=auth.uid());
REVOKE INSERT,UPDATE,DELETE ON public.iara_forecasts FROM anon,authenticated; REVOKE INSERT,UPDATE,DELETE ON public.iara_causal_diagnoses FROM anon,authenticated;
COMMIT;